import{_ as a,o as i,c as l,a0 as o}from"./chunks/framework.BFLrGO6w.js";const u=JSON.parse('{"title":"Overlay 對帳功能","description":"","frontmatter":{},"headers":[],"relativePath":"overlay-reconciliation.md","filePath":"overlay-reconciliation.md"}'),d={name:"overlay-reconciliation.md"};function c(s,e,r,t,n,h){return i(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="overlay-對帳功能" tabindex="-1">Overlay 對帳功能 <a class="header-anchor" href="#overlay-對帳功能" aria-label="Permalink to &quot;Overlay 對帳功能&quot;">​</a></h1><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>用 ACT overlay 的統計畫面作為對照組，檢查本地 parser 對同一份 log、同一把戰鬥算出的 DPS / HPS / 傷害 / 治療口徑是否一致。</p><p>目前第一個案例是 <code>pic/success.png</code>，對應 <code>logs/Network_30207_20260811.log</code> 的「熱舞綠光」通關場；FFLogs report <code>XDt7a138MhLqNbkx</code> 的 <code>fight=last</code> 已確認對應本機 pull 14（本機 log 在該通關後仍有其他 pull，因此不是本機最後一筆）。</p><h2 id="執行" tabindex="-1">執行 <a class="header-anchor" href="#執行" aria-label="Permalink to &quot;執行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare:overlay</span></span></code></pre></div><p>也可以指定其他案例檔：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare:overlay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> overlay/cases.json</span></span></code></pre></div><p>工具會優先讀 <code>public/data</code> 已產生資料；如果該 log 還沒有被 <code>npm run parse</code> 產生，就會直接讀原始 log 對帳，不會清掉或重寫網站資料。</p><h2 id="檔案" tabindex="-1">檔案 <a class="header-anchor" href="#檔案" aria-label="Permalink to &quot;檔案&quot;">​</a></h2><ul><li><code>overlay/cases.json</code>：設定 log、baseline、戰鬥名稱、選第幾把。</li><li><code>overlay/baselines/*.json</code>：人工抄錄 overlay 顯示值。<code>34k</code>、<code>20.2M</code> 這種縮寫會依 overlay 顯示精度容許四捨五入誤差。</li><li><code>src/parser/tools/compareOverlay.ts</code>：CLI 入口。</li><li><code>src/parser/validation/overlayComparison.ts</code>：欄位對帳邏輯。</li></ul><h2 id="目前已對帳欄位" tabindex="-1">目前已對帳欄位 <a class="header-anchor" href="#目前已對帳欄位" aria-label="Permalink to &quot;目前已對帳欄位&quot;">​</a></h2><ul><li>戰鬥：名稱、時間、Total DPS、Total HPS。</li><li>DPS 表：DPS、D%、Damage、Swing、直擊率、爆擊率、爆直率、MaxHit、死亡數。</li><li>HPS 表：HPS、H%、Healed、Eff.Heal、D.Shield、OverHeal、O.H。</li></ul><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><ul><li>目前不做 OCR，baseline 需要人工抄錄 overlay 數值。</li><li>第一版只對 screenshot 可見列；overlay 畫面未顯示的治療列不會被視為錯誤。</li><li>正式 parser 已將 Limit Break 拆成獨立 <code>Limit Break</code> 列；若仍有差異，代表 log 內事件筆數或 baseline 截圖口徑需要追查。</li><li>若對帳差異集中在 DPS / HPS，但總量接近，通常要優先檢查戰鬥起訖時間。</li><li>若差異集中在 Swing / MaxHit / Limit Break，通常要檢查 ACT 與本地 parser 的事件歸屬口徑。</li></ul><h2 id="_20260811-success-png-對帳現況" tabindex="-1">20260811 success.png 對帳現況 <a class="header-anchor" href="#_20260811-success-png-對帳現況" aria-label="Permalink to &quot;20260811 success.png 對帳現況&quot;">​</a></h2><p>最後更新：2026-08-29。</p><p>執行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/parser/tools/compareOverlay.ts</span></span></code></pre></div><p>parserVersion 53 的治療與傷害公式沿用 v47；使用 <code>--fresh</code> 直接解析 source 的重跑結果為 <code>compared=1, differences=67, invalid=0</code>。</p><p>已確認的改善與限制：</p><ul><li><code>Limit Break</code> 已從玩家傷害拆成獨立列，總傷仍包含 LB。</li><li>已確認 ACT overlay 截圖的 <code>Healed</code> 口徑是 <code>Eff.Heal + OverHeal + D.Shield</code>，也就是 <code>raw healing + direct shield</code>。</li><li>overlay 對帳使用 <code>(raw healing + direct shield) / active damage duration</code>；網站主表則採 FFLogs 優先的 <code>(effective healing + effective shield estimate) / pull duration</code>，兩者刻意分離。</li><li>網站治療表的 duration 是 <code>pull end - pull start</code>；overlay 對帳工具為了貼截圖，另用 active damage duration。</li><li><code>有效護盾(估)</code> 仍是本地估算值，不等於 overlay 的 D.Shield / FFLogs absorbs。</li><li>已修正 owner mapping：<code>OwnerID</code> 現在會套用到有 BNpc metadata 的寵物/地面效果，讓 <code>地星</code>、<code>卡邦庫爾-黃寶石</code>、<code>熾天使</code> 這類來源歸回玩家。</li><li>已移除不是 barrier 的 <code>F38</code> 太陽星座與 <code>764</code> 中間學派 self buff，加入 <code>F34</code> 建築神之塔；<code>762</code> / <code>763</code> 只阻擋多盾誤歸屬，不直接製造 absorb。</li><li>player damage 已排除敵方與 <code>E0000000</code> 環境來源的 DoT；本案例移除 <code>212,413</code> 假團隊傷害後，總傷為 <code>105,516,448</code>，與 FFLogs <code>105,549,649</code> 差 <code>-33,201</code>。</li><li><code>F36</code> 只有同來源、同目標的 <code>781</code> 中間學派仍有效時才建立護盾容量；F34 不再從 action line 合成全隊狀態。</li><li>可用 <code>npm run compare:overlay -- --fresh</code> 強制直接解析原始 log，避免誤讀舊 generated data。</li></ul><p>仍需追查的主要差異：</p><ul><li>戰鬥時間：排除開戰前仙女純治療、並在主目標 HP 歸零時結束後，本地 pull duration 已由 <code>10:51</code> 收斂為 <code>600.997s</code>，接近 FFLogs／overlay 的約 <code>10:00</code>。</li><li>Limit Break：本地 kill pull 只抓到 1 筆 <code>生者必滅</code>，overlay baseline 是 2 筆。</li><li>FFLogs <code>options=0</code> 精確基準：草莓香草可頌 <code>8,212,154</code>（effective <code>7,275,304</code> + absorbs <code>936,850</code>）；草灰妲 <code>7,049,289</code>（effective <code>3,964,614</code> + absorbs <code>3,084,675</code>）。parserVersion 44 本地含盾分別為 <code>7,950,451</code>、<code>6,982,316</code>，與 FFLogs 差 <code>-261,703</code>、<code>-66,973</code>；學者 absorbs <code>3,087,342</code> 僅差 <code>+2,667</code>。</li><li>parserVersion 53 AST D.Shield 保守估算為 <code>394,454</code>（F36 <code>256,740</code> + F34 <code>114,290</code> + 天星交錯 <code>23,424</code>），低於 overlay <code>895,400</code>／FFLogs <code>936,850</code>；缺口不以全隊合成狀態或報告常數回填。</li><li>Overlay raw Healed 仍有差異；原因主要是 effectId=0 無法完整拆分的 tick。</li><li>Hits / Swing / Crit / DH：overlay comparator 的比率只用有 action flags 的事件作分母，但 Swing 仍有大量差異，ACT 是否包含 miss／zero／其他 swing type 尚未確認。</li><li>MaxHit 技能名稱：部分技能名稱與 overlay 簡稱不同，例如 <code>天道回返雪月花</code> vs <code>天道回返</code>，需做顯示名稱 normalize，而不是改原始事件名。</li></ul><h2 id="公式調整計畫" tabindex="-1">公式調整計畫 <a class="header-anchor" href="#公式調整計畫" aria-label="Permalink to &quot;公式調整計畫&quot;">​</a></h2><h3 id="m1-對帳工具可信度" tabindex="-1">M1. 對帳工具可信度 <a class="header-anchor" href="#m1-對帳工具可信度" aria-label="Permalink to &quot;M1. 對帳工具可信度&quot;">​</a></h3><p>Status: Partial</p><p>目標：先確認 baseline 與本地 pull 是同一把，避免拿不同 encounter 修公式。</p><ul><li>[x] 建立 <code>npm run compare:overlay</code> 對帳入口。</li><li>[x] 建立 <code>pic/success.png</code> 對應的人工 baseline。</li><li>[x] 對帳工具使用 active damage duration 估算 overlay 顯示分母。</li><li>[x] 支援 <code>--fresh</code> 強制直接 parse，排除 generated data 陳舊干擾。</li><li>[ ] 在對帳輸出增加 local pull 摘要：start/end、pull duration、active damage duration、total damage、total raw healing、total healed。</li><li>[ ] 對 baseline 加上可選的 encounter duration / total damage / total healed 快速檢查。</li><li>[ ] 補一個「候選 pull ranking」輸出，列出同 boss 最接近 overlay total damage / duration 的 pulls。</li></ul><h3 id="m2-戰鬥時間分母" tabindex="-1">M2. 戰鬥時間分母 <a class="header-anchor" href="#m2-戰鬥時間分母" aria-label="Permalink to &quot;M2. 戰鬥時間分母&quot;">​</a></h3><p>Status: Planned</p><p>目標：釐清網站主表是否要使用 ACT overlay 相容分母。</p><ul><li>新增 <code>activeDamageDurationSeconds</code> 到 <code>PullSummary</code>。</li><li>DPS 對帳用 active damage duration；網站主表先保留 pull duration，旁邊顯示計算時間差異。</li><li>若 overlay 對帳穩定，再決定主 DPS 是否切換為 active damage duration。</li></ul><h3 id="m3-healing-來源覆蓋率" tabindex="-1">M3. Healing 來源覆蓋率 <a class="header-anchor" href="#m3-healing-來源覆蓋率" aria-label="Permalink to &quot;M3. Healing 來源覆蓋率&quot;">​</a></h3><p>Status: In progress</p><p>目標：先把治療分子對齊 overlay，尤其是草莓香草可頌 raw healing 缺口。</p><ul><li>[x] 確認 overlay <code>Healed = Eff.Heal + OverHeal + D.Shield = raw healing + direct shield</code>。</li><li>[x] 將 overlay comparison 的 HPS / Healed / H% / OverHeal% 改成含盾口徑。</li><li>[x] 修正 owner mapping，讓 <code>地星</code>、<code>卡邦庫爾-黃寶石</code>、<code>熾天使</code> 歸回玩家。</li><li>[x] 建立 healing-only debug CLI，輸出 by player / by ability / raw / effective / overheal / shield。</li><li>[x] 專查草莓香草可頌 raw healing 缺口；修正後由 <code>13.81M</code> 提升至 <code>19.64M</code>。</li><li>[x] 修正 <code>HoT abilityId=0</code> 把 AST tick 歸到 DPS / tank 自補的問題。</li><li>[x] 限制 <code>HoT abilityId=0</code> 只能回推到已確認的週期治療 status，多來源依 potency 權重拆分，無候選者保留為未歸屬列。</li><li>[ ] 檢查 action effect type 是否還有治療資訊不是 <code>04</code>，但不能把 <code>1B</code> 直接當 healing，因為 <code>1B</code> 大多是附加狀態 / ability id。</li></ul><h3 id="m4-shield-d-shield" tabindex="-1">M4. Shield / D.Shield <a class="header-anchor" href="#m4-shield-d-shield" aria-label="Permalink to &quot;M4. Shield / D.Shield&quot;">​</a></h3><p>Status: In progress</p><p>目標：維持 <code>有效護盾(估)</code>，不要誤稱正式 absorbs。</p><ul><li>[x] 已用 HP loss 差值估算實際吸收量，只在可歸因到單一 active shield status 時列入。</li><li>[x] 移除不是 barrier 的 <code>F38</code> / <code>764</code>，加入 <code>F34</code>；Horoscope <code>762</code> / <code>763</code> 僅作 overlap blocker。</li><li>[x] 多盾情境下，SCH <code>鼓舞</code> 不再吃掉所有可吸收量；parserVersion 53 為 <code>3.002M</code>，FFLogs <code>3.085M</code>。</li><li>[x] 普通 F36 不再誤算為中間學派護盾；F34 不再合成全隊狀態。</li><li>[ ] 對每筆 shielding estimate 輸出 debug reason：single shield / multiple shields / missing HP / no active shield。</li><li>[ ] 收斂 AST shield：目前 <code>0.394M</code> vs overlay <code>0.895M</code>（FFLogs absorbs <code>0.937M</code>），只補有逐事件證據的消耗。</li><li>[ ] 收斂 SCH 多盾歸因：目前約 <code>3.002M</code> vs overlay <code>3.5M</code>（FFLogs absorbs <code>3.085M</code>）。</li><li>[ ] 對比 overlay 的 D.Shield 時，標示為 estimate mismatch，不把它列為可 100% 對帳欄位。</li><li>[ ] 若未來能取得 ACT overlay 匯出資料，再研究是否能接近 overlay 的吸收歸屬。</li></ul><h3 id="m5-hit-swing-crit-dh" tabindex="-1">M5. Hit / Swing / Crit / DH <a class="header-anchor" href="#m5-hit-swing-crit-dh" aria-label="Permalink to &quot;M5. Hit / Swing / Crit / DH&quot;">​</a></h3><p>Status: Planned</p><p>目標：找出為什麼 overlay Swing 與本地 hits 差異大。</p><ul><li>分開顯示 action hits、DoT ticks、auto attacks、multi-hit effects。</li><li>對 DoT tick 沒有 crit/direct flags 的限制獨立標示。</li><li>先確認 overlay 的 Swing 是否包含 DoT ticks、HoT/damage tick、miss/zero/multi-effect。</li></ul><h3 id="m6-顯示名稱-normalize" tabindex="-1">M6. 顯示名稱 normalize <a class="header-anchor" href="#m6-顯示名稱-normalize" aria-label="Permalink to &quot;M6. 顯示名稱 normalize&quot;">​</a></h3><p>Status: Planned</p><p>目標：避免技能名稱長短不同造成假差異。</p><ul><li>對 MaxHit ability 加 overlay display name normalize。</li><li>保留原始 log ability name，不修改 parser 原始資料。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>做 M4 的 shield debug reason，逐事件收斂 AST / SCH shield 差異。</li><li>追查剩餘 raw healing 缺口，並檢查是否還有非 <code>04</code> 的可證明治療 effect。</li><li>治療穩定後，再做 M2 / M5 / M6，開始對 DPS 分母、Swing、crit/DH 與顯示名稱。</li></ol>',51)])])}const g=a(d,[["render",c]]);export{u as __pageData,g as default};
